UPDATE ums_member
SET integration = integration - #{use}
WHERE id = #{memberId} AND integration >= #{use}

UPDATE ums_member
SET integration = IFNULL(integration, 0) + #{amount}
WHERE id = #{memberId}

UPDATE pms_sku_stock
SET lock_stock = IFNULL(lock_stock, 0) + #{qty}
WHERE id = #{skuId} AND stock - IFNULL(lock_stock, 0) >= #{qty}
